package com.bank.qa.story;

import java.util.logging.*;

public class AutomationStoryDemo {
    private static final Logger log = Logger.getLogger(AutomationStoryDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new StoryLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // BEFORE: slow, flaky, untrusted — did not gate releases.
        SuiteMetrics before = new SuiteMetrics("BEFORE", 18.0, 42, 320, false);
        // AFTER: the initiative's result.
        SuiteMetrics after = new SuiteMetrics("AFTER", 0.5, 9, 1100, true);

        log.info("=== Challenging automation problem — measurable outcome ===");
        log.info("Original problem: regression suite slow+flaky -> stopped gating releases -> defects shipped");
        log.info("Why hard: many interacting flakiness causes + shared data blocked parallelism");
        log.info("Investigation: measured flakiness over 100 runs, classified failures via traces/logs");
        log.info("Solution: auto-waiting asserts, role-based locators, per-worker data isolation, "
            + "storage-state auth, mocked 3rd-party, sharded CI with trace artifacts");
        log.info("Trade-offs: temporary visible retries + quarantine while fixing roots; eng time invested");
        log.info("IMPROVEMENT: " + after.improvementOver(before));
        log.info("Learned: flakiness is a defect to DIAGNOSE not retry; data isolation unlocks parallelism; "
            + "a suite's value is the trust people place in it");
    }
}

// ─── Would be in StoryLogFormatter.java in a real project ───
class StoryLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
